/** Public development fixtures only; no inference or installed corpus changes. */
public final class ComparisonInstrumentation extends Instrumentation {
 Bundle args;String run;File dir,marker;Activity activity;JSONObject report=new JSONObject(),state;JSONArray checks=new JSONArray();
 interface Action{void run()throws Exception;}
 void ok(boolean value,String name){if(!value)throw new AssertionError(name);checks.put(name);}
 void reject(Action action,String name)throws Exception{try{action.run();}catch(Exception e){checks.put(name);return;}throw new AssertionError(name);}
 public void onCreate(Bundle b){args=b;start();}
 void await(BooleanSupplier b,String name)throws Exception{long until=SystemClock.elapsedRealtime()+15000;while(!b.getAsBoolean()&&SystemClock.elapsedRealtime()<until)Thread.sleep(40);ok(b.getAsBoolean(),name);}
 Button button(View v,String text){if(v instanceof Button&&((Button)v).getText().toString().equals(text))return (Button)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){Button b=button(((ViewGroup)v).getChildAt(i),text);if(b!=null)return b;}return null;}
 void click(String label){runOnMainSync(()->{Button b=button(activity.getWindow().getDecorView(),label);if(b==null)throw new AssertionError("Missing control "+label);b.performClick();});}
 void close(){if(activity!=null){Activity a=activity;runOnMainSync(a::finish);waitForIdleSync();activity=null;}}
 void saveState()throws Exception{Files.write(marker.toPath(),state.toString().getBytes(StandardCharsets.UTF_8));}
 String originals()throws Exception{JSONArray rows=new JSONArray();try(NotebookStore n=new NotebookStore(getTargetContext())){for(NotebookStore.Entry e:n.list("",false))rows.put(new JSONArray().put(e.id).put(ComparisonStore.identity(e)).put(e.note).put(e.bookmark));}return ComparisonStore.hash(rows.toString());}
 void screenshot(String name)throws Exception{waitForIdleSync();Thread.sleep(250);android.graphics.Bitmap b=getUiAutomation().takeScreenshot();try(FileOutputStream out=new FileOutputStream(new File(dir,name+".png"))){ok(b!=null&&b.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out),name+"_screenshot");}StringBuilder text=new StringBuilder();nodes(getUiAutomation().getRootInActiveWindow(),text);Files.write(new File(dir,name+"-accessibility.txt").toPath(),text.toString().getBytes(StandardCharsets.UTF_8));}
 void nodes(android.view.accessibility.AccessibilityNodeInfo n,StringBuilder s){if(n==null)return;s.append(n.getClassName()).append(" | ").append(n.getText()).append(" | ").append(n.getContentDescription()).append(" | clickable=").append(n.isClickable()).append('\n');for(int i=0;i<n.getChildCount();i++)nodes(n.getChild(i),s);}
 void cleanup()throws Exception{close();ComparisonStore c=new ComparisonStore(getTargetContext());JSONArray ids=state.getJSONArray("comparisons");for(int i=0;i<ids.length();i++){JSONObject candidate=c.load(ids.getString(i));Set<Long> owned=new HashSet<>();for(int j=0;j<state.getJSONArray("records").length();j++)owned.add(state.getJSONArray("records").getLong(j));ok(owned.contains(candidate.getJSONArray("subjects").getJSONObject(0).getLong("record"))&&owned.contains(candidate.getJSONArray("subjects").getJSONObject(1).getLong("record")),"cleanup_owned_comparison");c.remove(ids.getString(i));}try(NotebookStore n=new NotebookStore(getTargetContext())){JSONArray records=state.getJSONArray("records");for(int i=0;i<records.length();i++){long id=records.getLong(i);try{NotebookStore.Entry e=n.get(id);ok(e.title.startsWith("T440 "+run+" "),"cleanup_owned_record");n.remove(id);getTargetContext().getSharedPreferences("SourceReaderActivity",0).edit().remove("position-"+id+"--1").commit();}catch(IllegalArgumentException missing){}}}ok(originals().equals(state.getString("originals")),"original_notebook_records_retained");report.put("original_records_sha256",originals());}
 JSONObject addComparison(ComparisonStore store,long a,long b)throws Exception{JSONObject d=store.create(a,b);store.save(d);state.getJSONArray("comparisons").put(d.getString("id"));saveState();return d;}
 void first()throws Exception{
  state=new JSONObject().put("originals",originals()).put("records",new JSONArray()).put("comparisons",new JSONArray());saveState();
  String fixture;try(InputStream in=getContext().getAssets().open("cases.json")){fixture=new String(in.readAllBytes(),StandardCharsets.UTF_8);}ok(ComparisonStore.hash(fixture).equals("210225f3530e44141bc6ed8c180ad13c822ce870d9628194fc093b646fe695d3"),"frozen_fixture_identity");
  ComparisonStore store=new ComparisonStore(getTargetContext());JSONArray cases=new JSONObject(fixture).getJSONArray("cases");JSONObject last=null;
  for(int k=0;k<cases.length();k++){JSONObject example=cases.getJSONObject(k);long[] records=new long[2];try(NotebookStore n=new NotebookStore(getTargetContext())){for(int j=0;j<2;j++){JSONObject source=example.getJSONArray("sources").getJSONObject(j);ok(ComparisonStore.hash(source.getString("body")).equals(source.getString("sha256")),"source_fixture_hash");records[j]=n.add("source","T440 "+run+" "+source.getString("title"),"",source.getString("body"),"Constructed public development fixture; not licensed corpus evidence or a verified factual answer.",false);state.getJSONArray("records").put(records[j]);saveState();}}
   JSONObject d=addComparison(store,records[0],records[1]);JSONArray names=example.getJSONArray("dimensions");for(int i=0;i<names.length();i++)ComparisonStore.addDimension(d,names.getString(i));ok(store.portable(d).contains("Unknown"),"initial_unknown_"+k);
   JSONObject subject=d.getJSONArray("subjects").getJSONObject(0);NotebookStore.Entry source=store.source(subject);JSONObject quote=store.bind(subject,0,Math.min(source.body.length(),40));d.getJSONArray("dimensions").getJSONObject(0).getJSONArray("cells").put(0,quote);String binding=quote.toString();ComparisonStore.move(d,0,1);d.getJSONArray("dimensions").getJSONObject(1).put("name","Renamed personal dimension");ComparisonStore.swap(d);ok(d.getJSONArray("dimensions").getJSONObject(1).getJSONArray("cells").getJSONObject(1).toString().equals(binding),"reorder_swap_binding_"+k);store.save(d);if(k==0){String ownedId=d.getString("id");File ownedFile=store.file(ownedId);byte[] original=Files.readAllBytes(ownedFile.toPath());try{Files.write(ownedFile.toPath(),"{broken".getBytes());reject(()->store.load(ownedId),"corrupt_store_denied");}finally{Files.write(ownedFile.toPath(),original);}}d=store.load(d.getString("id"));ok(store.portable(d).contains(quote.getString("quote")),"persist_literal_"+k);
   JSONObject valid=store.bind(subject,0,4),bad=new JSONObject(valid.toString());bad.put("quote","Invented");ok(store.cell(subject,bad).startsWith("Unknown"),"corrupt_literal_gap");bad=new JSONObject(valid.toString()).put("source_hash","0".repeat(64));ok(store.cell(subject,bad).startsWith("Unknown"),"corrupt_hash_gap");bad=new JSONObject(valid.toString()).put("start",1);ok(store.cell(subject,bad).startsWith("Unknown"),"stale_offset_gap");JSONObject missing=new JSONObject(subject.toString()).put("record",Long.MAX_VALUE);ok(store.cell(missing,valid).startsWith("Unknown"),"missing_source_gap");
   while(d.getJSONArray("dimensions").length()<6)ComparisonStore.addDimension(d,"Extra dimension");JSONObject capped=d;reject(()->ComparisonStore.addDimension(capped,"Seventh"),"six_dimension_limit");last=d;
  }
  JSONObject unicode=last.getJSONArray("subjects").getJSONObject(1);reject(()->store.bind(unicode,3,4),"split_surrogate_denied");
  long research;try(NotebookStore n=new NotebookStore(getTargetContext())){research=n.add("research","T440 "+run+" research","","Unverified research body","Not source evidence",false);}state.getJSONArray("records").put(research);saveState();long first=state.getJSONArray("records").getLong(0),second=state.getJSONArray("records").getLong(1);reject(()->store.create(first,research),"research_record_denied");
  // Actual Saved creation action, using two explicit SOURCE selections.
  activity=startActivitySync(new Intent(getTargetContext(),SavedActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));SavedActivity saved=(SavedActivity)activity;await(()->saved.records.getChildCount()>0,"saved_records_visible");runOnMainSync(()->{saved.selected.add(first);saved.selected.add(second);});click("Notebook actions");ActivityMonitor monitor=addMonitor(ComparisonActivity.class.getName(),null,false);click("Compare selected (2)");Activity opened=waitForMonitorWithTimeout(monitor,15000);removeMonitor(monitor);ok(opened instanceof ComparisonActivity,"saved_creates_grid");activity=opened;ComparisonActivity grid=(ComparisonActivity)activity;await(()->grid.data!=null&&!grid.busy,"grid_opened");String id=grid.data.getString("id");state.getJSONArray("comparisons").put(id);state.put("ui_id",id);saveState();
  runOnMainSync(()->grid.change(()->{grid.data.put("title","T440 workspace "+run);ComparisonStore.addDimension(grid.data,"Condition");}));await(()->!grid.busy,"dimension_saved");click("Choose quote 1 / 1");await(()->grid.quoteText!=null,"quote_selection_dialog");runOnMainSync(()->{Selection.setSelection((Spannable)grid.quoteText.getText(),0,5);});
  // Native dialog action invokes the actual selection handler.
  await(()->getUiAutomation().getRootInActiveWindow()!=null&&!getUiAutomation().getRootInActiveWindow().findAccessibilityNodeInfosByText("Use selection").isEmpty(),"quote_dialog_accessibility_ready");android.view.accessibility.AccessibilityNodeInfo root=getUiAutomation().getRootInActiveWindow();List<android.view.accessibility.AccessibilityNodeInfo> matches=root.findAccessibilityNodeInfosByText("Use selection");ok(!matches.isEmpty(),"quote_confirm_accessible");android.view.accessibility.AccessibilityNodeInfo confirm=null;for(android.view.accessibility.AccessibilityNodeInfo n:matches)if(n.isClickable()&&n.getClassName().toString().contains("Button"))confirm=n;ok(confirm!=null&&confirm.performAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_CLICK),"actual_quote_button_clicked");await(()->{try{return !grid.busy&&!grid.data.getJSONArray("dimensions").getJSONObject(0).getJSONArray("cells").isNull(0);}catch(Exception e){return false;}},"selected_quote_saved");
  runOnMainSync(()->{Button view=button(grid.getWindow().getDecorView(),"Open source 1 / 1");if(view!=null)view.requestRectangleOnScreen(new android.graphics.Rect(0,0,view.getWidth(),view.getHeight()),true);});screenshot("manual-grid");String quote=grid.data.getJSONArray("dimensions").getJSONObject(0).getJSONArray("cells").getJSONObject(0).getString("quote");ok(quote.equals("Water"),"ui_exact_selected_quote");
  ActivityMonitor readerMonitor=addMonitor(SourceReaderActivity.class.getName(),null,false);click("Open source 1 / 1");Activity reader=waitForMonitorWithTimeout(readerMonitor,15000);removeMonitor(readerMonitor);ok(reader instanceof SourceReaderActivity,"source_link_activity");SourceReaderActivity sourceReader=(SourceReaderActivity)reader;await(()->sourceReader.content!=null,"exact_source_reader_loaded");ok(sourceReader.entry.id==first,"exact_source_reader_identity");runOnMainSync(reader::finish);waitForIdleSync();
  runOnMainSync(()->{grid.note.setText("Personal comparison note; not source evidence.");});click("Save comparison note");await(()->!grid.busy,"note_saved");
  ActivityMonitor recreate=addMonitor(ComparisonActivity.class.getName(),null,false);runOnMainSync(grid::recreate);Activity restored=waitForMonitorWithTimeout(recreate,15000);removeMonitor(recreate);ok(restored instanceof ComparisonActivity,"grid_recreated");activity=restored;ComparisonActivity current=(ComparisonActivity)activity;await(()->current.data!=null,"restored_loaded");ok(store.portable(current.data).contains("Water")&&current.data.getString("note").startsWith("Personal"),"recreation_retains_quote_note");
  runOnMainSync(()->current.change(()->ComparisonStore.addDimension(current.data,"Date")));await(()->!current.busy,"second_dimension_saved");click("Move dimension 1 down");await(()->!current.busy,"ui_reorder_saved");click("Swap subjects");await(()->!current.busy,"ui_subject_swap_saved");ok(current.data.getJSONArray("dimensions").getJSONObject(1).getJSONArray("cells").getJSONObject(1).getString("quote").equals("Water"),"ui_reorder_swap_exact_binding");String exported=store.portable(current.data);Files.write(new File(dir,"comparison-export.txt").toPath(),exported.getBytes(StandardCharsets.UTF_8));ok(exported.contains("Unknown")&&exported.contains("UTF-16 [0, 5)")&&exported.contains("SHA-256"),"portable_gap_identity_offsets");
  runOnMainSync(()->{current.onActivityResult(NotebookActivity.EXPORT_DOCUMENT,Activity.RESULT_CANCELED,null);});ok(current.operation.getText().toString().contains("cancelled"),"picker_cancel_preserves_grid");
  File text=new File(dir,"provider-stress.txt");Files.write(text.toPath(),("Test-only blocked export transport fixture; not comparison evidence.\n".repeat(4096)).getBytes(StandardCharsets.UTF_8));Uri blocked=Uri.parse("content://org.pocketlore.fixture.comparison/"+run+"/stall"),success=Uri.parse("content://org.pocketlore.fixture.comparison/"+run+"/success");
  runOnMainSync(()->current.writeDocument(text,blocked));await(()->getTargetContext().getContentResolver().call(blocked,"status",null,null).getBoolean("opened"),"blocked_provider_open");Thread.sleep(150);long start=SystemClock.elapsedRealtime();runOnMainSync(current::cancelExport);await(()->current.exportJob==null,"blocked_export_cancelled");report.put("cancel_ms",SystemClock.elapsedRealtime()-start);getTargetContext().getContentResolver().call(blocked,"release",null,null);Files.write(text.toPath(),exported.getBytes(StandardCharsets.UTF_8));runOnMainSync(()->current.writeDocument(text,success));await(()->current.exportJob==null,"export_retry_completed");try(InputStream in=getTargetContext().getContentResolver().openInputStream(success)){ok(Arrays.equals(in.readAllBytes(),exported.getBytes(StandardCharsets.UTF_8)),"export_retry_exact_bytes");}
  click("Clear cell 2 / 2");await(()->!current.busy,"clear_saved");ok(store.portable(current.data).contains("Unknown"),"clear_unknown_gap");screenshot("unknown-grid");state.put("expected_export",store.portable(current.data));JSONObject coldExports=new JSONObject();for(int k=0;k<state.getJSONArray("comparisons").length();k++){String key=state.getJSONArray("comparisons").getString(k);coldExports.put(key,store.portable(store.load(key)));}state.put("cold_exports",coldExports);report.put("stored_comparison_bytes",store.file(current.data.getString("id")).length());saveState();close();report.put("comparison_id",id).put("phase","first");
 }
 void cold()throws Exception{state=new JSONObject(new String(Files.readAllBytes(marker.toPath()),StandardCharsets.UTF_8));ComparisonStore store=new ComparisonStore(getTargetContext());String id=state.getString("ui_id");JSONObject exports=state.getJSONObject("cold_exports");int quoted=0;for(Iterator<String> it=exports.keys();it.hasNext();){String key=it.next();String actual=store.portable(store.load(key));ok(actual.equals(exports.getString(key)),"cold_each_comparison_exact");if(actual.contains("Literal quote (manual selection"))quoted++;}ok(quoted==3,"cold_persisted_quote_bindings");JSONObject d=store.load(id);ok(store.portable(d).equals(state.getString("expected_export")),"cold_store_exact_export");activity=startActivitySync(new Intent(getTargetContext(),SavedActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));click("Notebook actions");ActivityMonitor m=addMonitor(ComparisonActivity.class.getName(),null,false);click("Open saved comparisons");await(()->getUiAutomation().getRootInActiveWindow()!=null&&!getUiAutomation().getRootInActiveWindow().findAccessibilityNodeInfosByText("T440 workspace "+run).isEmpty(),"saved_comparison_discoverable");android.view.accessibility.AccessibilityNodeInfo item=getUiAutomation().getRootInActiveWindow().findAccessibilityNodeInfosByText("T440 workspace "+run).get(0);if(!item.isClickable())item=item.getParent();ok(item.performAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_CLICK),"saved_comparison_reopen_click");Activity reopened=waitForMonitorWithTimeout(m,15000);removeMonitor(m);ok(reopened instanceof ComparisonActivity,"saved_comparison_reopened");activity=reopened;ComparisonActivity grid=(ComparisonActivity)activity;await(()->grid.data!=null,"cold_grid_reopened");ok(grid.data.getString("note").startsWith("Personal"),"cold_note_retained");screenshot("cold-grid");cleanup();report.put("phase","cold");}
 @Override public void onStart(){boolean pass=false;try{run=args.getString("run_id");ok(run!=null&&run.matches("[A-Za-z0-9-]+"),"run_identity");dir=new File(getTargetContext().getFilesDir(),"comparison-check-"+run);marker=new File(dir,"state.json");if(args.getString("phase","").equals("cleanup")){state=new JSONObject(new String(Files.readAllBytes(marker.toPath()),StandardCharsets.UTF_8));cleanup();}else if(args.getString("phase","").equals("cold")){cold();}else{ok(dir.mkdir(),"owned_fixture_directory");first();}pass=true;}catch(Throwable e){try{report.put("error",android.util.Log.getStackTraceString(e));if(state!=null)try{cleanup();}catch(Exception cleanup){report.put("cleanup_error",cleanup.toString());}}catch(Exception ignored){}}finally{close();try{report.put("run_id",run).put("source_manifest_sha256",args.getString("source_manifest_sha256")).put("sdk",Build.VERSION.SDK_INT).put("checks",checks).put("status",pass?"PASS":"FAIL");Files.write(new File(dir,args.getString("phase","").equals("cold")?"cold.json":"report.json").toPath(),report.toString(2).getBytes(StandardCharsets.UTF_8));Bundle b=new Bundle();b.putString("comparison_receipt",report.toString());finish(pass?Activity.RESULT_OK:Activity.RESULT_CANCELED,b);}catch(Exception e){finish(Activity.RESULT_CANCELED,new Bundle());}}}
}
